SELECT 
FROM product

    status = 3
    AND stock > 0
    AND deleted = 0

        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category_id = #{categoryId}


        AND campus = #{campus}


        AND price >= #{minPrice}


        AND price <= #{maxPrice}


ORDER BY created_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
